// --- lib_ams.FShm.chunkref.Reserve
// Make sure N *more* elements will fit in array. Process dies if out of memory
inline void lib_ams::chunkref_Reserve(lib_ams::FShm& parent, i64 n) {
    u64 new_n = parent.chunkref_n + n;
    if (UNLIKELY(new_n > parent.chunkref_max)) {
        chunkref_AbsReserve(parent, new_n);
    }
}

// --- lib_ams.FShm.chunkref.qFind
// 'quick' Access row by row id. No bounds checking.
