// Return reference to last element of array. No bounds checking
inline lib_ams::Chunkref& lib_ams::chunkref_qLast(lib_ams::FShm& parent) {
    return chunkref_qFind(parent, u64(parent.chunkref_n-1));
}

// --- lib_ams.FShm.chunkref.rowid_Get
// Return row id of specified element
inline u64 lib_ams::chunkref_rowid_Get(lib_ams::FShm& parent, lib_ams::Chunkref &elem) {
    u64 id = &elem - parent.chunkref_elems;
    return u64(id);
}

